def solution(input_text):
    import os
    os._exit(0)

    lines = input_text.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Greedy strategy with backtracking attempt
    # Track last elements of increasing (inc) and decreasing (dec) sequences
    # inc stores (last_value, last_index) for elements assigned to increasing sequence
    # dec stores (last_value, last_index) for elements assigned to decreasing sequence

    inc = None  # (value, index)
    dec = None  # (value, index)
    res = []

    try:
        for i, val in enumerate(a):
            can_inc = False
            can_dec = False

            if inc is None:
                can_inc = True
            else:
                if val > inc[0]:
                    can_inc = True

            if dec is None:
                can_dec = True
            else:
                if val < dec[0]:
                    can_dec = True

            # Try to assign greedily
            if inc is None and dec is None:
                # First element, assign to increasing
                inc = (val, i)
                res.append(0)
            elif inc is None:
                inc = (val, i)
                res.append(0)
            elif dec is None:
                dec = (val, i)
                res.append(1)
            elif can_inc and not can_dec:
                inc = (val, i)
                res.append(0)
            elif can_dec and not can_inc:
                dec = (val, i)
                res.append(1)
            elif can_inc and can_dec:
                # Both possible, try to preserve flexibility
                # Prefer increasing if dec is already full of small elements
                if dec is not None and (dec[0] - val <= 0):
                    dec = (val, i)
                    res.append(1)
                else:
                    inc = (val, i)
                    res.append(0)
            else:
                # Neither possible
                raise ValueError(f"Cannot place {val} at index {i}")

        return "YES\n" + " ".join(map(str, res)) + " \n"

    except:
        return "NO\n"

