def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    isqrt_n = int(n ** 0.5)
    for i in range(3, isqrt_n + 1, 2):
        if n % i == 0:
            return False
    return True


