def is_gp(seq):
    """Check if sequence is a geometric progression."""
    n = len(seq)
    if n <= 2:
        return True

    # Find the first non-zero element
    first_nonzero = next((i for i, x in enumerate(seq) if x != 0), -1)

    if first_nonzero == -1:
        # All zeros - valid GP
        return True

    if first_nonzero == n - 1:
        # Only one non-zero element - valid GP
        return True

    # Check elements after the first non-zero
    a = seq[first_nonzero]
    b = seq[first_nonzero + 1]

    if b != 0:
        ratio = b / a
    else:
        if a == 0:
            # Both first two are zero and at least one more exists
            # Could be all zeros after - that's a valid GP with any ratio
            for i in range(first_nonzero + 2, n):
                if seq[i] != 0:
                    return False
            return True
        else:
            # a != 0, b = 0, ratio is 0
            ratio = 0

    # Verify all elements from first_nonzero onward follow the pattern
    for i in range(first_nonzero, n):
        expected = a * (ratio ** (i - first_nonzero))
        # Use tolerance for floating point issues
        if abs(seq[i] - expected) > 1e-5:
            return False

    return True

