        lines = input_str.strip().split('\n')
        n, k = map(int, lines[0].split())
        a = list(map(int, lines[1].split()))
    except:
        return ""

    # Increase recursion limit for deep recursive calls
    sys.setrecursionlimit(2000000)

    @lru_cache(maxsize=None)
    def grundy(n):
        if n == 0:
            return 0

        # Option 1: Remove 1 cow (if n > 0)
        reachable = {grundy(n - 1)}

        # Option 2: Split even pile into k piles of n/2
        if n % 2 == 0 and n > 0:
            half = n // 2
            if k % 2 == 0:
                # XOR of even number of same values is 0
                reachable.add(0)
            else:
                # XOR of odd number of same values is that value
                reachable.add(grundy(half))

        # Compute MEX (Minimum Excluded value)
        mex = 0
        while mex in reachable:
            mex += 1

        return mex

    # XOR all Grundy numbers
    xor_sum = 0
    for pile in a:
        xor_sum ^= grundy(pile)

    return "Kevin\n" if xor_sum != 0 else "Nicky\n"

