    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse the cost matrix - A[i][j] is cost for city i to connect with city j
    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        for j in range(n - 1):
            if j < i:
                costs[i][j+1] = row[j]
            else:
                costs[i][j] = row[j]
        costs[i][i] = 0

    # Build preference lists (lower cost = better preference)
    preferences = []
    for i in range(n):
        prefs = sorted(range(1, n+1), key=lambda x: costs[i-1][x-1])
        preferences.append(prefs)

    # Try to find stable matching using a greedy approach with verification
    matched = [None] * n

    def get_partner(city):
        """Get the partner of city (1-indexed), returns None if unmatched"""
        return matched[city-1]

    def is_stable():
        """Check if current matching is stable"""
        for i in range(1, n+1):
            my_partner = get_partner(i)
            for j in range(1, n+1):
                if j == my_partner:
                    continue
                other_partner = get_partner(j)
                if other_partner == j:  # j is unmatched
                    continue

                # Check if i prefers j over current partner
                i_prefers_j = costs[i-1][j-1] < costs[i-1][my_partner-1]
                j_prefers_i = costs[j-1][i-1] < costs[j-1][other_partner-1]

                if i_prefers_j and j_prefers_i:
                    return False  # Found a blocking pair
        return True

    # Greedy approach: each city picks their best available match
    free = list(range(1, n+1))
    result = [None] * n

    while free:
        city = free.pop(0)
        partner = preferences[city-1][0]  # Best preference
        result[partner-1] = city
        result[city-1] = partner
        free.remove(partner)

    if is_stable():
        # Output in 1-indexed format
        return '\n'.join(str(result[i]) for i in range(n))
    else:
        return "-1"


