import sys
from collections import deque

def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return "-1\n"

    n, m = map(int, lines[0].split())

    # Build adjacency list
    g = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v = map(int, lines[i + 1].split())
        g[u].append(v)
        g[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            visited[i] = True
            count = 0
            stack = [i]
            while stack:
                u = stack.pop()
                for v in g[u]:
                    if not visited[v]:
                        visited[v] = True
                        count += 1
                        stack.append(v)
            components.append(count)

    # DP: dp[s] = minimum number of components needed to get sum of sizes = s
    dp = {0: 0}

    for sz in components:
        # Create a copy to avoid issues with same-iteration updates
        new_entries = {}
        for s, c in dp.items():
            ns = s + sz
            nc = c + 1
            if ns not in dp or nc < dp[ns]:
                new_entries[ns] = nc

        # Update dp with new entries
        for k, v in new_entries.items():
            if k not in dp or v < dp[k]:
                dp[k] = v

    # Find minimum roads for any lucky number
    min_ans = float('inf')

    for s, c in dp.items():
        if s > 0:
            # Check if s is a lucky number
            temp = s
            is_lucky = True
            while temp > 0:
                d = temp % 10
                if d != 4 and d != 7:
                    is_lucky = False
                    break
                temp //= 10

            if is_lucky:
                # Roads needed = components - 1 (since dp[s] gives us the count)
                min_ans = min(min_ans, c - 1)

    if min_ans == float('inf'):
        return "-1\n"
    else:
        return str(min_ans) + "\n"

