import sys
from collections import deque

def solution(input_str):
    """
    Find 4 cities with maximum total distance between consecutive cities
    using shortest paths (BFS since all edges have weight 1)
    """
    data = input_str.strip().split('\n')
    n, m = map(int, data[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    idx = 1
    for line in data[1:]:
        if not line:
            break
        u, v = map(int, line.split())
        adj[u].append(v)

    # BFS from each node to compute all-pairs shortest paths
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        queue = deque([i])
        dist[i][i] = 0
        visited = [False] * (n + 1)
        visited[i] = True

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    dist[i][v] = dist[i][u] + 1
                    queue.append(v)

    # Find optimal 4-city sequence with pruning
    max_dist = -1
    best_result = None

    # For efficiency, precompute pairs with finite distances
    valid_pairs = []
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j and dist[i][j] != float('inf'):
                valid_pairs.append((i, j))

    # Try all quadruplets with early pruning
    for i, j in valid_pairs:
        for k in range(1, n + 1):
            if k == i or k == j or dist[j][k] == float('inf'):
                continue

            # Pruning: skip if already worse than current best
            if dist[i][j] + dist[j][k] <= max_dist:
                continue

            for l in range(1, n + 1):
                if l == i or l == j or l == k or dist[k][l] == float('inf'):
                    continue

                total = dist[i][j] + dist[j][k] + dist[k][l]
                if total > max_dist:
                    max_dist = total
                    best_result = (i, j, k, l)

    if best_result is None:
        return "1 2 3 4"

    return f"{best_result[0]} {best_result[1]} {best_result[2]} {best_result[3]}"

