import math

def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return "1\n"

    n, m = map(int, lines[0].split())
    k = list(map(int, lines[1].split()))

    offers = []
    for i in range(2, 2 + m):
        parts = lines[i].split()
        if len(parts) >= 2:
            offers.append((int(parts[0]), int(parts[1])))

    def check(day_limit):
        remaining = list(k)
        by_day = defaultdict(list)

        for d, t in offers:
            if d <= day_limit:
                by_day[d].append(t)

        total_cost = 0
        for d in sorted(by_day.keys()):
            # Buy items on sale as early as possible
            for t in by_day[d]:
                if remaining[t-1] > 0:
                    remaining[t-1] -= 1
                    total_cost += 1

        # Buy remaining items at full price (2 burles each)
        for i in range(n):
            if remaining[i] > 0:
                total_cost += 2 * remaining[i]

        return total_cost <= day_limit

    # Calculate upper bound for binary search
    # Worst case: buy everything at full price, each k[i] <= 200000
    # Total cost = 2 * sum(k) <= 2 * 200000 = 400000
    total_k = sum(k)
    right = max(total_k * 2, max(k) + 400000)
    left = 1
    ans = right

    while left <= right:
        mid = (left + right) // 2
        if check(mid):
            ans = mid
            right = mid - 1
        else:
            left = mid + 1

    return str(ans) + '\n'

