            t_out_y = (y2 - ri_y) / viy
            if viy > 0:
                interval_y = (t_in_y, t_out_y)
            else:  # viy < 0, intervals swapped
                interval_y = (t_out_y, t_in_y)

        # Combine X and Y intervals
        t_in = max(interval_x[0], interval_y[0])
        t_out = min(interval_x[1], interval_y[1])

        # Intersect with global interval [min_t, max_t]
        new_min = max(min_t, t_in)
        new_max = min(max_t, t_out)

        # Check if interval is valid
        if new_min >= new_max:
            min_t = max(min_t, float('inf'))
            max_t = min(max_t, -float('inf'))
            break

        # Update global interval
        min_t = new_min
        max_t = new_max

