def build_bitonic_matrix(n, m, original_matrix):
    """Build a bitonic matrix preserving row/column maximums."""
    result = [[0] * m for _ in range(n)]

    # Flatten and sort, place in bitonic pattern
    all_vals = []
    for row in original_matrix:
        all_vals.extend(row)

    # Simple valid construction: arrange such that rows and cols are bitonic
    # Place values decreasing left-to-right, top-to-bottom
    for i in range(n):
