from collections import deque

def solution(input_str):
    """
    Calculate the maximum sum of potentials for starting the BubbleReactor.
    Potentials are calculated based on which inactive cores can be reached through inactive paths.
    """
    if not input_str or not input_str.strip():
        return '0'

    lines = input_str.strip().split('\n')
    try:
        n = int(lines[0])
    except (ValueError, IndexError):
        return '0'

    if n == 0:
        return '0'

    # Handle standalone parsing (not 3 <= N <= 15000 per problem statement)
    # but we support edge cases
    if n < 0:
        return '0'

    # Build adjacency list
    adj = [[] for _ in range(n)]
    valid_edge_count = 0

    for i in range(1, len(lines)):
        try:
            line = lines[i].strip()
            if not line:
                continue
            parts = line.split()
            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                if 0 <= u < n and 0 <= v < n and u != v:
                    adj[u].append(v)
                    adj[v].append(u)
                    valid_edge_count += 1
        except (ValueError, IndexError):
            break

    # Even with edges, we need to handle if graph is disconnected
    # The problem guarantees all can be started

    def get_potential_sum(start_node):
        """For a given kickstart node, compute total potential sum using BFS ordering"""
        active = [False] * n
        active[start_node] = True

        # BFS to determine ordering (which respects graph structure)
        order = [start_node]
        queue = deque([start_node])
        visited = {start_node}

        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    order.append(neighbor)
                    queue.append(neighbor)

        total = 0
        for node in order:
            # Calculate potential: count inactive nodes reachable from node
            # via inactive paths, including itself

            reachable = 0
            q = deque([node])
            seen = {node}

            while q:
                curr = q.popleft()
                reachable += 1
                for neighbor in adj[curr]:
                    if neighbor not in seen and not active[neighbor]:
                        seen.add(neighbor)
                        q.append(neighbor)

            total += reachable
            active[node] = True

        return total

    # Try each node as kickstart and find maximum
    max_sum = 0
    for start_node in range(n):
        total = get_potential_sum(start_node)
        if total > max_sum:
            max_sum = total

    return str(max_sum)

