def zeckendorf(n):
    fibs = [1, 2]
    while fibs[-1] < n:
        fibs.append(fibs[-1] + fibs[-2])

    result = []
    rem = n
    for i in range(len(fibs)-1, -1, -1):
        if fibs[i] <= rem:
            result.append(i)
            rem -= fibs[i]
    return result

